mapper.select:
select * from good

    and category_id=#{categoryId}
    and status=#{status}

order by create_time desc

select g.*,c.name as categoryName from good g left outer join category c on g.category_id=c.id

     and g.name like concat('%',#{name},'%')
     and g.category_id=#{categoryId}
     and g.status=#{status}

order by g.create_time desc
